FuncDef.Code:
float opFiniteRepeatXZ(inout vec3 p, float spacingX, float spacingZ, int repX, int repZ)
{
    vec2 spacing        = vec2(spacingX, spacingZ);
    vec2 repetitions    = vec2(repX, repZ);

    // cell index
    vec2 halfsize = spacing*0.5;
    vec2 c = floor((p.xz + halfsize)/spacing);
    float cellIndex = c.x + c.y + PI * sin(c.x * c.y);

    //p.xz = min(p.xz, p.xz - spacing * clamp(round(p.xz / spacing), -repetitions, repetitions));
    p.xz = p.xz - spacing * clamp(round(p.xz / spacing), vec2(0.0), repetitions);

    return cellIndex;
}
